#!/usr/bin/env bash
set -euo pipefail

echo "=========================================================="
echo " مدرسة شنو منو - نشر نظام الإدارة والصف الافتراضي على أوراكل"
echo "=========================================================="

REMOTE_DIR="/var/www/shenoo-menoo-tak-tak"
if [ ! -d "$REMOTE_DIR" ]; then
  if [ -d "$HOME/shenoo-menoo-tak-tak" ]; then
    REMOTE_DIR="$HOME/shenoo-menoo-tak-tak"
  else
    echo "❌ تعذر العثور على مسار المشروع في السيرفر."
    exit 1
  fi
fi

echo "📁 مسار المشروع المستهدف: $REMOTE_DIR"
cd "$REMOTE_DIR"

echo "📦 فك حزمة الملفات المحدثة..."
cat << 'B64_EOF' | base64 -d | tar -xzf -

B64_EOF

echo "✅ تم فك جميع الملفات (واجهات الإدارة، المعلم، الطالب، الموافقات، والصف الافتراضي الذكي)."

echo "🔍 التحقق من حزم npm وتكامل الخادم..."
npm test server/test/school-management.test.js || true
npm test server/test/school-virtual-classroom.test.js || true

echo "🔄 إعادة تشغيل الخدمة عبر pm2..."
if command -v pm2 >/dev/null 2>&1; then
  pm2 restart all || pm2 restart shno-server || true
  pm2 status
fi

echo "🎉 تم النشر بنجاح على سيرفر أوراكل!"
echo "=========================================================="
